function ruleBasedSpam(text) {
  const rules = ['выиграл', 'приз', 'скидка'];
  return rules.some((r) => text.includes(r)) ? 'spam' : 'ok';
}

// Вариант 2: оценки, «выученные» из данных (здесь — заготовка)
const learnedScores = {
  'выиграл приз': 0.97,
  'встречаемся завтра': 0.03,
  'ваша скидка ждёт': 0.91,
};

function learnedSpam(text) {
  const score = learnedScores[text] ?? 0.5;
  return score > 0.9 ? 'spam' : 'ok';
}

console.log(ruleBasedSpam('выиграл миллион'));
console.log(learnedSpam('ваша скидка ждёт'));

