function estimateTokens(text) {
  const words = text.trim().split(/\s+/).filter(Boolean).length;
  return Math.ceil(words / 0.75); // приблизительно: 0,75 слова на токен
}

const systemPrompt = 'You are a helpful assistant for a small shop.';
const userQuestion = 'What is your return policy for shoes?';
const budget = 30;

const used = estimateTokens(systemPrompt) + estimateTokens(userQuestion);
console.log('used:', used, 'fits:', used <= budget);

