function isVerdict(value) {
  if (typeof value !== 'object' || value === null) return false;
  if (typeof value.topic !== 'string' || value.topic === '') return false;
  const allowed = ['positive', 'negative', 'neutral'];
  return allowed.includes(value.sentiment);
}

function tryVerdict(raw) {
  try {
    const parsed = JSON.parse(raw);
    return isVerdict(parsed) ? parsed : null;
  } catch (e) {
    return null;
  }
}

const ok = tryVerdict('{"topic":"delivery","sentiment":"neutral"}');
const rejected = tryVerdict('{"topic":"delivery","sentiment":"so-so"}');

console.log(ok === null ? 'invalid' : ok.topic + '/' + ok.sentiment);
console.log(rejected === null ? 'invalid' : 'accepted');

