  return a + b;
}

const tools = { getWeather, addNumbers };

// «Модель» просит вызвать инструмент (имитация ответа модели)
const modelResponse = {
  tool: 'getWeather',
  args: { city: 'Dushanbe' },
};

const fn = tools[modelResponse.tool];
if (!fn) {
  console.log('tool not available:', modelResponse.tool);
} else {
  console.log(modelResponse.tool, '->', fn(modelResponse.args.city));
}

