function getWeather(city) {
  const data = { Dushanbe: 'sunny +28', Moscow: 'rain +9' };
  return data[city] || 'unknown city';
}

function addNumbers(a, b) {
  return a + b;
}

const tools = { getWeather, addNumbers };

const modelTurns = [
  { tool: 'addNumbers', args: { a: 7, b: 5 } },
  { tool: 'getWeather', args: { city: 'Moscow' } },
];

const log = [];
for (const turn of modelTurns) {
  const fn = tools[turn.tool];
  if (!fn) {
    log.push(turn.tool + ' -> not available');
    continue;
  }
  const value =
    turn.tool === 'addNumbers'
      ? fn(turn.args.a, turn.args.b)
      : fn(turn.args.city);
  log.push(turn.tool + ' -> ' + value);
}
console.log(log.join(' | '));

