const price = { input: 0.000003, output: 0.000015 };

function requestCost(inputTokens, outputTokens) {
  return inputTokens * price.input + outputTokens * price.output;
}

const requests = [
  { name: 'short', in: 200, out: 100 },
  { name: 'with-history', in: 3000, out: 300 },
  { name: 'retry', in: 1000, out: 200 },
];

let total = 0;
for (const r of requests) {
  const c = requestCost(r.in, r.out);
  total += c;
  console.log(r.name, c.toFixed(4));
}
console.log('total', total.toFixed(4));

