const messages = [
  'Не приходит SMS-код, второй день жду',
  'Хочу вернуть деньги за заказ 512',
  'Здравствуйте, вы работаете в субботу?',
];

function classify(text) {
  const t = text.toLowerCase();
  if (t.includes('код') || t.includes('ошибка')) {
    return { category: 'technical', priority: 'high', needsHuman: false };
  }
  if (t.includes('вернуть') || t.includes('деньги')) {
    return { category: 'refund', priority: 'high', needsHuman: true };
  }
  return { category: 'general', priority: 'low', needsHuman: false };
}

function isVerdict(v) {
  return (
    typeof v === 'object' &&
    v !== null &&
    ['technical', 'refund', 'general'].includes(v.category) &&
    ['low', 'high'].includes(v.priority) &&
    typeof v.needsHuman === 'boolean'
  );
}

const log = [];
for (const message of messages) {
  const verdict = classify(message);
  if (!isVerdict(verdict)) {
    log.push('invalid verdict -> ' + message);
    continue;
  }
  log.push(
    verdict.category +
      '/' +
      verdict.priority +
      (verdict.needsHuman ? ' human' : ' auto')
  );
}
console.log(log.join('\n'));

